#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Event {
    Deposit { id: u64, amount: u64 },
    Withdraw { id: u64, amount: u64 },
}

impl Event {
    pub fn id(&self) -> u64 {
        match self {
            Self::Deposit { id, .. } | Self::Withdraw { id, .. } => *id,
        }
    }
}

